const hasNegativeLedInventoryTimeline = `-- name: HasNegativeLedInventoryTimeline :one
SELECT EXISTS (
    SELECT 1
    FROM (
        SELECT sum(quantity_delta_micros) OVER (
            PARTITION BY warehouse_object_id, product_object_id
            ORDER BY effective_date,
                     CASE WHEN entry_type = 'OPENING' THEN 0 ELSE 1 END,
                     occurred_at, id
            ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW
        ) AS running_quantity
        FROM led_inventory_entries
        WHERE generation_id = $1
    ) timeline
    WHERE running_quantity < 0
)::boolean
`

func (q *Queries) HasNegativeLedInventoryTimeline(ctx context.Context, generationID string) (bool, error) {
	row := q.db.QueryRow(ctx, hasNegativeLedInventoryTimeline, generationID)
	var column_1 bool
	err := row.Scan(&column_1)
	return column_1, err
}

